export const fold = value => value.toLowerCase().replace(/[\[\]\\^]/g,c=>({'[':'{',']':'}','\\':'|','^':'~'}[c]));
export function parse(line) {
 let rest=line.replace(/[\r\n]+$/,''); const result={tags:{},prefix:'',command:'',params:[]};
 if(rest[0]==='@'){const end=rest.indexOf(' ');if(end<0)return null;for(const t of rest.slice(1,end).split(';')){const [k,...v]=t.split('=');result.tags[k]=v.join('=');}rest=rest.slice(end+1);}
 if(rest[0]===':'){const end=rest.indexOf(' ');if(end<0)return null;result.prefix=rest.slice(1,end);rest=rest.slice(end+1);}
 const split=rest.indexOf(' :');let tail;if(split>=0){tail=rest.slice(split+2);rest=rest.slice(0,split);}const tokens=rest.trim().split(/ +/);result.command=tokens.shift().toUpperCase();result.params=tokens;if(tail!==undefined)result.params.push(tail);return result.command?result:null;
}
export function validateLine(line){if(!line||/[\r\n\0]/.test(line))throw Error('Commands must be a single line.');if(new TextEncoder().encode(line).length>510)throw Error('Message is too long for IRC. Please shorten it.');return line;}
export function serviceCommand(action,values,preview=false){return action.command.replace(/\{(\w+)\}/g,(_,id)=>{const f=action.fields.find(f=>f.id===id);const value=(values[id]||'').trim();if(/[\r\n\0]/.test(value))throw Error('Line breaks are not allowed.');if(!value&&!f?.optional)throw Error(`Enter ${f?.label||id}.`);if(!['command','message','reason','topic','description','value'].includes(id)&&/\s/.test(value))throw Error(`${f?.label||id} cannot contain spaces.`);return preview&&f?.secure&&value?'••••••':value;}).trim();}
export function toWire(input,target){validateLine(input);if(input[0]!=='/'){if(!target||target==='Server')throw Error('Select a channel or private conversation first.');return validateLine(`PRIVMSG ${target} :${input}`);}const [c,...args]=input.slice(1).split(' ');const body=args.join(' ');const aliases={ns:'NickServ',cs:'ChanServ',ms:'MemoServ',os:'OperServ',hs:'HostServ',bs:'BotServ'};if(aliases[c.toLowerCase()])return validateLine(`PRIVMSG ${aliases[c.toLowerCase()]} :${body}`);switch(c.toLowerCase()){case 'me':if(!target||target==='Server')throw Error('Choose a conversation first.');return validateLine(`PRIVMSG ${target} :\x01ACTION ${body}\x01`);case 'msg':case 'notice':{const i=body.indexOf(' ');if(i<1)throw Error('Use /msg nickname message.');return validateLine(`${c.toLowerCase()==='msg'?'PRIVMSG':'NOTICE'} ${body.slice(0,i)} :${body.slice(i+1)}`);}case 'quote':case 'raw':return validateLine(body);case 'quit':case 'away':return validateLine(`${c.toUpperCase()} :${body}`);default:return validateLine(input.slice(1));}}
export function readable(text){return text.replace(/\x03(?:\d{1,2}(?:,\d{1,2})?)?/g,'').replace(/[\x00-\x09\x0b-\x1f\x7f]/g,'');}
